insert into public.questoes (id, modulo_id, tipo, enunciado, apoio, alternativas, correta, pares, explicacao, fonte, dificuldade, ativo) values
  ('hist.c6.m1.q01', 'hist.c6.m1', 'mc', 'Por volta de que ano surgiram os primeiros povoamentos urbanos no Brasil?', null, '["Por volta de 1530, quando os portugueses passaram a morar no país.","Por volta de 1900, com a produção de café.","Por volta de 1808, com a chegada da família real.","Por volta de 1957, quando Natal cresceu."]'::jsonb, 0, null, 'Os primeiros povoamentos urbanos surgiram por volta de 1530, quando os portugueses passaram a morar no Brasil. Depois vieram as vilas, com casas, igrejas e comércios.', 'L3 p.16', 2, true),
  ('hist.c6.m1.q02', 'hist.c6.m1', 'mc', 'Qual é a ordem certa do crescimento de uma cidade espontânea?', null, '["Povoado ➜ vila ➜ cidade","Cidade ➜ vila ➜ povoado","Vila ➜ povoado ➜ cidade","Projeto ➜ obra ➜ cidade"]'::jsonb, 0, null, 'Primeiro nasce um pequeno povoado, ele cresce e vira vila e, depois de muito tempo, vira cidade.', 'L3 p.16 e p.34', 2, true),
  ('hist.c6.m1.q03', 'hist.c6.m1', 'mc', 'O que são cidades espontâneas?', null, '["Cidades que surgiram e se desenvolveram sem planejamento.","Cidades desenhadas por um arquiteto antes de existirem.","Cidades construídas só para serem capitais.","Cidades que foram destruídas pelo mar."]'::jsonb, 0, null, 'Espontâneas são as cidades que foram crescendo sozinhas, aos poucos, sem ninguém planejar antes.', 'L3 p.16 e p.34', 2, true),
  ('hist.c6.m1.q04', 'hist.c6.m1', 'mc', 'Qual é o nome da primeira vila brasileira e em que ano ela foi fundada?', null, '["São Vicente, em 1532","Salvador, em 1549","Recife, em 1637","Rio de Janeiro, em 1808"]'::jsonb, 0, null, 'A primeira vila brasileira foi São Vicente, fundada em 1532, perto do mar, no estado de São Paulo.', 'L3 p.16', 2, true),
  ('hist.c6.m1.q05', 'hist.c6.m1', 'mc', 'Por que a Vila de São Vicente foi crescendo até virar cidade?', null, '["Por causa do comércio pelo porto, da criação de gado, do cultivo de alimentos e, principalmente, dos engenhos de açúcar.","Por causa da produção de café.","Porque a família real portuguesa foi morar lá.","Porque foi escolhida para ser a capital do Brasil."]'::jsonb, 0, null, 'São Vicente cresceu com o comércio de mercadorias pelo porto, a criação de gado, o cultivo de alimentos e, principalmente, os engenhos de açúcar construídos pelos portugueses.', 'L3 p.16', 2, true),
  ('hist.c6.m1.q06', 'hist.c6.m1', 'mc', 'Por que a Vila de São Vicente precisou ser reconstruída?', null, '["Porque em 1542 o mar invadiu e destruiu ruas, casas e a igreja.","Porque um incêndio destruiu a vila.","Porque os moradores se mudaram para Brasília.","Porque os holandeses reformaram a vila."]'::jsonb, 0, null, 'Em 1542 o mar invadiu a vila e destruiu grande parte dela. Por isso, ela foi reconstruída um pouco mais distante da praia.', 'L3 p.16 e p.34', 2, true),
  ('hist.c6.m1.q07', 'hist.c6.m1', 'vf', 'As primeiras vilas brasileiras precisaram ser reformadas e modernizadas com o passar dos anos, por causa das necessidades de seus moradores.', null, '["Verdadeiro","Falso"]'::jsonb, 0, null, 'Verdadeiro! As ruas ficaram mais largas e muitas casas e construções foram feitas.', 'L3 p.16', 2, true),
  ('hist.c6.m1.q08', 'hist.c6.m1', 'mc', 'A obra Fundação de São Vicente, produzida em 1900 por Benedito Calixto, representa:', null, '["Povos indígenas e portugueses na Vila de São Vicente.","A família real chegando ao Rio de Janeiro.","A construção de Brasília.","O Viaduto do Chá em São Paulo."]'::jsonb, 0, null, 'Nessa pintura aparecem povos indígenas e portugueses na Vila de São Vicente.', 'L3 p.16', 2, true),
  ('hist.c6.m1.q09', 'hist.c6.m1', 'vf', 'São Vicente foi uma cidade planejada, desenhada antes de ser construída.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! São Vicente nasceu de uma vila que foi crescendo aos poucos: ela é uma cidade espontânea.', 'L3 p.16 e p.34', 2, true),
  ('hist.c6.m1.q10', 'hist.c6.m1', 'mc', 'Observando as duas fotos da cidade de Natal (1957 e atualmente), o que mudou na paisagem?', null, '["Hoje há muitos prédios, casas, ruas e uma ponte; antes havia mais vegetação e poucas construções.","Antes havia mais prédios do que hoje.","A cidade continua exatamente igual.","Hoje só existe vegetação no lugar da cidade."]'::jsonb, 0, null, 'A paisagem urbana de Natal se transformou: a cidade cresceu, ganhou muitas construções e a vegetação diminuiu.', 'L3 p.14 e p.15', 2, true),
  ('hist.c6.m2.q01', 'hist.c6.m2', 'mc', 'Em que estado fica a cidade de Recife?', null, '["Pernambuco","Bahia","Rio Grande do Norte","Tocantins"]'::jsonb, 0, null, 'Recife é a capital de Pernambuco.', 'L3 p.17', 2, true),
  ('hist.c6.m2.q02', 'hist.c6.m2', 'mc', 'Entre quais anos Recife passou por uma reforma urbana feita pelos holandeses?', null, '["Entre 1637 e 1644","Entre 1808 e 1821","Entre 1530 e 1542","Entre 1970 e 1990"]'::jsonb, 0, null, 'Recife foi reformada entre 1637 e 1644, quando era administrada por holandeses.', 'L3 p.17 e p.34', 2, true),
  ('hist.c6.m2.q03', 'hist.c6.m2', 'mc', 'O que os holandeses construíram na cidade de Recife?', null, '["Ruas, pontes, casas, jardim botânico e zoológico","Só igrejas e engenhos de açúcar","Avenidas largas e prédios monumentais","Canaletas exclusivas para ônibus"]'::jsonb, 0, null, 'Nessa época os holandeses construíram ruas, pontes, casas, um jardim botânico e um zoológico.', 'L3 p.17 e p.34', 2, true),
  ('hist.c6.m2.q04', 'hist.c6.m2', 'mc', 'O Palácio de Friburgo, em Recife, foi construído para ser a moradia de quem?', null, '["De Maurício de Nassau","Do rei de Portugal","De Lúcio Costa","De Benedito Calixto"]'::jsonb, 0, null, 'O Palácio de Friburgo foi a moradia de Maurício de Nassau, que governou a cidade durante a administração holandesa.', 'L3 p.17', 2, true),
  ('hist.c6.m2.q05', 'hist.c6.m2', 'vf', 'As construções feitas em Recife nessa época demonstravam a riqueza de parte da população.', null, '["Verdadeiro","Falso"]'::jsonb, 0, null, 'Verdadeiro! As construções mostravam que parte da população era rica.', 'L3 p.17', 2, true),
  ('hist.c6.m2.q06', 'hist.c6.m2', 'mc', 'Quem administrava a cidade de Recife na época dessa grande reforma?', null, '["Os holandeses","Os franceses","A família real portuguesa","Os fazendeiros de café"]'::jsonb, 0, null, 'Recife era administrada por holandeses entre 1637 e 1644.', 'L3 p.17', 2, true),
  ('hist.c6.m2.q07', 'hist.c6.m2', 'assoc', 'Ligue cada cidade ao motivo pelo qual ela mudou:', null, null, null, '[["São Vicente","O mar invadiu a vila em 1542"],["Recife","Reformas feitas pelos holandeses"],["Rio de Janeiro","Chegada da família real portuguesa"],["São Paulo","Riquezas da produção de café"]]'::jsonb, 'São Vicente foi reconstruída depois da invasão do mar; Recife foi reformada pelos holandeses; o Rio mudou com a família real; São Paulo se modernizou com o dinheiro do café.', 'L3 p.16 a p.18 e p.34', 2, true),
  ('hist.c6.m3.q01', 'hist.c6.m3', 'mc', 'Entre quais anos a cidade do Rio de Janeiro passou por grandes reformas?', null, '["Entre 1808 e 1821","Entre 1637 e 1644","Entre 1530 e 1532","Entre 1892 e 1938"]'::jsonb, 0, null, 'O Rio de Janeiro foi reformado entre 1808 e 1821, quando a família real portuguesa veio para o Brasil.', 'L3 p.17', 2, true),
  ('hist.c6.m3.q02', 'hist.c6.m3', 'mc', 'Por que a família real portuguesa resolveu deixar Portugal?', null, '["Porque estava em conflito com a França e queria fugir de uma possível guerra.","Porque queria construir uma nova capital.","Porque Portugal foi destruído pelo mar.","Porque queria plantar café no Brasil."]'::jsonb, 0, null, 'A família real estava em conflito com a França e saiu de Portugal para fugir de uma possível guerra.', 'L3 p.17', 2, true),
  ('hist.c6.m3.q03', 'hist.c6.m3', 'mc', 'Quem veio junto com a família real portuguesa para o Rio de Janeiro?', null, '["Soldados, comerciantes e funcionários públicos","Apenas o rei e a rainha","Trabalhadores vindos de Brasília","Engenheiros holandeses"]'::jsonb, 0, null, 'A família real trouxe soldados, comerciantes e funcionários públicos. Por isso o número de habitantes aumentou muito.', 'L3 p.17', 2, true),
  ('hist.c6.m3.q04', 'hist.c6.m3', 'mc', 'O embarque da Família Real Portuguesa para o Brasil, obra de Nicolas-Louis-Albert Delerive, mostra um evento que provocou, na época:', null, '["O aumento da população da cidade do Rio de Janeiro.","A ida da população brasileira para Portugal.","A eleição de um novo presidente do Brasil.","A construção da cidade de Brasília."]'::jsonb, 0, null, 'Com a chegada da família real e de seus acompanhantes, a população do Rio de Janeiro aumentou bastante.', 'L3 p.19, atividade 3', 2, true),
  ('hist.c6.m3.q05', 'hist.c6.m3', 'mc', 'Quais construções foram feitas no Rio de Janeiro com a chegada do rei e de sua família?', null, '["Estradas, o Museu Nacional, a Biblioteca Real, o Observatório Astronômico e o Jardim Botânico","Canaletas de ônibus e ciclovias","O Viaduto do Chá e a Avenida Paulista","O Palácio de Friburgo e um zoológico"]'::jsonb, 0, null, 'Em pouco tempo a paisagem urbana mudou: foram construídas estradas, o Museu Nacional, a Biblioteca Real, o Observatório Astronômico e o Jardim Botânico.', 'L3 p.18', 2, true),
  ('hist.c6.m3.q06', 'hist.c6.m3', 'mc', 'O Jardim Botânico do Rio de Janeiro, construído há mais de 200 anos, é um espaço muito antigo da cidade. Marque a alternativa correta:', null, '["O Jardim Botânico faz parte das modificações acontecidas na cidade por causa da chegada dos portugueses.","Essa construção serviu como moradia para os novos habitantes portugueses, já que faltavam moradias para todos.","O Jardim Botânico foi construído pelos holandeses.","O Jardim Botânico foi planejado por Lúcio Costa."]'::jsonb, 0, null, 'O Jardim Botânico foi uma das construções feitas depois que os portugueses chegaram ao Rio de Janeiro.', 'L3 p.20, atividade 4', 2, true),
  ('hist.c6.m3.q07', 'hist.c6.m3', 'mc', 'Qual problema apareceu no Rio de Janeiro quando muita gente chegou de uma vez?', null, '["Faltou moradia: as melhores casas foram tomadas pelos funcionários da família real e entregues aos portugueses.","Faltou água para todos os moradores.","As ruas ficaram largas demais.","O mar invadiu as casas da cidade."]'::jsonb, 0, null, 'A falta de moradia foi um problema. As melhores casas foram tomadas e entregues aos portugueses.', 'L3 p.18', 2, true),
  ('hist.c6.m3.q08', 'hist.c6.m3', 'vf', 'As pessoas que foram obrigadas a deixar suas casas para os portugueses ficaram muito satisfeitas com essa mudança.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Essa situação provocou o descontentamento das pessoas que perderam suas moradias.', 'L3 p.18', 2, true),
  ('hist.c6.m3.q09', 'hist.c6.m3', 'mc', 'A obra O chafariz do campo, produzida em 1835 por Karl Wilhelm Theremin, retrata:', null, '["Uma fonte, construção que se tornou importante quando a família real veio ao Brasil.","O porto da Vila de São Vicente.","A construção de Brasília.","O zoológico construído em Recife."]'::jsonb, 0, null, 'As fontes (chafarizes) se tornaram construções importantes na época em que a família real portuguesa veio ao Brasil.', 'L3 p.18', 2, true),
  ('hist.c6.m3.q10', 'hist.c6.m3', 'mc', 'Por que o Brasil foi o destino escolhido pela família real portuguesa?', null, '["Porque, nesse período, o Brasil também era administrado pelos portugueses.","Porque o Brasil já era a capital de Portugal.","Porque o Brasil tinha acabado de ser planejado.","Porque os holandeses convidaram a família real."]'::jsonb, 0, null, 'Como o Brasil era administrado pelos portugueses na época, a família real decidiu partir para o Rio de Janeiro.', 'L3 p.17', 2, true),
  ('hist.c6.m4.q01', 'hist.c6.m4', 'mc', 'Em que época a cidade de São Paulo passou por mudanças que a deixaram mais moderna?', null, '["Nos anos de 1900","Nos anos de 1530","Entre 1637 e 1644","Nos anos de 1970"]'::jsonb, 0, null, 'Nos anos de 1900 São Paulo passou por reformas que modernizaram a cidade.', 'L3 p.18', 2, true),
  ('hist.c6.m4.q02', 'hist.c6.m4', 'mc', 'Escreva dois exemplos de reformas feitas em São Paulo nessa época. Qual alternativa apresenta exemplos corretos?', null, '["A abertura de ruas e avenidas e a criação de praças","A construção de um zoológico e de um jardim botânico pelos holandeses","A construção do Museu Nacional e da Biblioteca Real","O desenho da cidade em formato de avião"]'::jsonb, 0, null, 'Entre as reformas de São Paulo estão a abertura de ruas e avenidas, a criação de praças e a iluminação das ruas do centro.', 'L3 p.18 e p.20, atividade 5a', 2, true),
  ('hist.c6.m4.q03', 'hist.c6.m4', 'mc', 'Que produto comercializado pelo Brasil nessa época contribuiu para a modernização de São Paulo?', null, '["O café","O açúcar","O chá-da-Índia","O ouro"]'::jsonb, 0, null, 'As riquezas vieram da produção de café, plantado na região. Por muitos anos ele foi o principal produto comercializado pelo Brasil.', 'L3 p.18 e p.20, atividade 5b', 2, true),
  ('hist.c6.m4.q04', 'hist.c6.m4', 'mc', 'Onde moravam as famílias que ficaram ricas com o café, em São Paulo?', null, '["Em casarões construídos na cidade","Em vilas de pescadores","Em prédios monumentais de Brasília","No Palácio de Friburgo"]'::jsonb, 0, null, 'O dinheiro do café enriqueceu muitas pessoas, que viviam com suas famílias em casarões na cidade. Isso aparece na foto da Avenida Paulista de 1910.', 'L3 p.18', 2, true),
  ('hist.c6.m4.q05', 'hist.c6.m4', 'mc', 'Em que ano foi inaugurado o Viaduto do Chá, o primeiro viaduto da cidade de São Paulo?', null, '["Em 1892","Em 1938","Em 1910","Em 1821"]'::jsonb, 0, null, 'O Viaduto do Chá foi inaugurado em 1892 e foi o primeiro viaduto de São Paulo.', 'L3 p.20, texto da atividade 6', 2, true),
  ('hist.c6.m4.q06', 'hist.c6.m4', 'mc', 'Por que o Viaduto do Chá recebeu esse nome?', null, '["Porque nas suas proximidades ficava uma extensa plantação de chá-da-Índia.","Porque foi construído por uma família chamada Chá.","Porque nele funcionavam muitas casas de chá.","Porque o piso dele era feito de folhas de chá."]'::jsonb, 0, null, 'O nome veio da extensa plantação de chá-da-Índia que existia perto do local.', 'L3 p.20, texto da atividade 6', 2, true),
  ('hist.c6.m4.q07', 'hist.c6.m4', 'mc', 'Qual era o objetivo da construção do Viaduto do Chá?', null, '["Ligar a Rua Direita à Rua do Chá (atual Rua Barão de Itapetininga), no centro da cidade.","Ligar São Paulo ao Rio de Janeiro.","Levar água até o centro da cidade.","Servir de moradia para os fazendeiros de café."]'::jsonb, 0, null, 'O viaduto foi construído para ligar a Rua Direita com a Rua do Chá, hoje chamada Rua Barão de Itapetininga.', 'L3 p.20, texto da atividade 6', 2, true),
  ('hist.c6.m4.q08', 'hist.c6.m4', 'mc', 'O que aconteceu com o Viaduto do Chá em 1938?', null, '["O velho viaduto de piso de madeira foi demolido e deu lugar a outro, de concreto, com o dobro de largura.","Ele foi destruído pelo mar.","Ele foi transformado em um museu.","Ele ganhou canaletas exclusivas para ônibus."]'::jsonb, 0, null, 'Em 1938 o viaduto antigo, com piso de madeira, foi demolido. No lugar dele foi construído um de concreto, com o dobro de largura.', 'L3 p.20, texto da atividade 6', 2, true),
  ('hist.c6.m4.q09', 'hist.c6.m4', 'mc', 'Comparando as imagens do Viaduto do Chá por volta de 1900 e atualmente, que mudanças você observa?', null, '["Hoje há muitos prédios altos, mais carros e menos casas baixas; a paisagem ficou mais movimentada.","Hoje há menos construções do que antes.","A paisagem continua exatamente igual.","Hoje o viaduto é feito de madeira."]'::jsonb, 0, null, 'Na imagem antiga aparecem construções baixas; hoje o lugar tem prédios altos, muitos carros e uma paisagem bem mais urbanizada.', 'L3 p.20, atividade 6b', 2, true),
  ('hist.c6.m4.q10', 'hist.c6.m4', 'vf', 'As reformas urbanas citadas no texto do Viaduto do Chá aconteceram na cidade do Rio de Janeiro.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! O Viaduto do Chá fica na cidade de São Paulo.', 'L3 p.20, atividade 6a', 2, true),
  ('hist.c6.m5.q01', 'hist.c6.m5', 'mc', 'As cidades planejadas são aquelas que:', null, '["Foram planejadas e projetadas antes de se formarem.","Se formaram naturalmente ao longo do tempo.","Foram planejadas depois de terem se formado.","Cresceram a partir de povoados sem projeto."]'::jsonb, 0, null, 'Cidades planejadas são pensadas detalhadamente antes mesmo de sua construção começar.', 'L3 p.24 e p.30, atividade 1', 2, true),
  ('hist.c6.m5.q02', 'hist.c6.m5', 'mc', 'O que costuma ser indicado no projeto de uma cidade planejada?', null, '["O comprimento e a largura das ruas, a localização de casas, parques, postos de saúde, escolas, comércio e prédios da administração pública.","Apenas o nome que a cidade vai ter.","Somente a quantidade de moradores.","Apenas a localização do porto."]'::jsonb, 0, null, 'Nos projetos das cidades planejadas tudo é pensado antes: ruas, moradias, parques, postos de saúde, escolas, comércio e prédios públicos.', 'L3 p.24', 2, true),
  ('hist.c6.m5.q03', 'hist.c6.m5', 'mc', 'Quais são exemplos de cidades brasileiras planejadas citados no livro?', null, '["Teresina, Belo Horizonte e Palmas","Recife, Salvador e Natal","São Vicente, Manaus e Florianópolis","São Paulo, Rio de Janeiro e Recife"]'::jsonb, 0, null, 'Teresina (PI), Belo Horizonte (MG) e Palmas (TO) são exemplos de cidades planejadas.', 'L3 p.24', 2, true),
  ('hist.c6.m5.q04', 'hist.c6.m5', 'mc', 'Por que a cidade de Brasília foi planejada?', null, '["Para se tornar a capital do Brasil.","Para ser uma cidade-fortaleza.","Para receber o porto de açúcar.","Para abrigar a família real portuguesa."]'::jsonb, 0, null, 'Brasília foi planejada para se tornar a capital do país. Hoje tem avenidas largas, áreas verdes e prédios monumentais.', 'L3 p.24 e p.35', 2, true),
  ('hist.c6.m5.q05', 'hist.c6.m5', 'mc', 'Quem criou o desenho da cidade de Brasília?', null, '["O arquiteto Lúcio Costa","O engenheiro Jorge de Macedo","O engenheiro Roberto Brandão","Maurício de Nassau"]'::jsonb, 0, null, 'O desenho de Brasília foi criado pelo arquiteto Lúcio Costa.', 'L3 p.24', 2, true),
  ('hist.c6.m5.q06', 'hist.c6.m5', 'mc', 'Brasília foi projetada em formato de avião. O que esse formato simbolizava?', null, '["O progresso e a modernização pelos quais o país estava passando na época.","A importância dos aeroportos para o Brasil.","A vontade de construir a cidade em pouco tempo.","A proteção contra a invasão de estrangeiros."]'::jsonb, 0, null, 'O formato de avião era símbolo dos processos de progresso e modernização que o país vivia.', 'L3 p.24', 2, true),
  ('hist.c6.m5.q07', 'hist.c6.m5', 'mc', 'Por que construir Brasília foi um grande desafio?', null, '["Porque a região era isolada, de difícil acesso e pouco povoada.","Porque a região era cercada pelo mar.","Porque já existiam muitas construções no local.","Porque faltava café na região."]'::jsonb, 0, null, 'Como a região era isolada, de difícil acesso e pouco povoada, milhares de trabalhadores tiveram que se deslocar de outras partes do país.', 'L3 p.25', 2, true),
  ('hist.c6.m5.q08', 'hist.c6.m5', 'mc', 'Morar em Brasília custava caro. O que isso provocou?', null, '["Muitos trabalhadores foram morar em regiões próximas, formando cidades ao redor da capital, que cresceram sem planejamento.","Todos os trabalhadores voltaram para suas cidades de origem.","A cidade parou de ser construída.","O governo diminuiu o tamanho das avenidas."]'::jsonb, 0, null, 'As cidades ao redor de Brasília cresceram de maneira improvisada, sem planejamento, o que provocou problemas urbanos e sociais que ainda não foram totalmente resolvidos.', 'L3 p.25', 2, true),
  ('hist.c6.m5.q09', 'hist.c6.m5', 'mc', 'Em quanto tempo Brasília foi construída?', null, '["Em pouco mais de três anos","Em mais de cem anos","Entre 1637 e 1644","Em cerca de vinte anos"]'::jsonb, 0, null, 'Brasília foi construída em pouco mais de três anos, com o trabalho de milhares de pessoas vindas de todo o Brasil.', 'L3 p.25 e p.35', 2, true),
  ('hist.c6.m5.q10', 'hist.c6.m5', 'mc', 'Sobre a cidade de Goiânia, é correto afirmar que:', null, '["Foi a primeira cidade brasileira planejada no século 20, com influência do estilo Art Déco, e visava ao desenvolvimento do interior do Brasil.","Foi a primeira vila fundada no Brasil, em 1532.","Foi planejada pelos holandeses para ser uma cidade-fortaleza.","Nunca foi planejada: cresceu a partir de um povoado."]'::jsonb, 0, null, 'Goiânia foi planejada para 50 mil habitantes (hoje tem mais de 1,4 milhão de pessoas) e o processo visava ao desenvolvimento do interior do Brasil.', 'L3 p.26', 2, true),
  ('hist.c6.m5.q11', 'hist.c6.m5', 'mc', 'Por que Salvador, capital da Bahia, é considerada uma cidade planejada?', null, '["Porque foi pensada em 1549 para ser uma espécie de \"cidade-fortaleza\", administrativa e militar, e foi a primeira sede do Governo Geral do Brasil.","Porque foi projetada em formato de avião.","Porque foi reformada pelos holandeses entre 1637 e 1644.","Porque foi construída para ser a capital do país."]'::jsonb, 0, null, 'O planejamento de Salvador, em 1549, a colocava como cidade administrativa e militar, uma espécie de "cidade-fortaleza".', 'L3 p.26', 2, true),
  ('hist.c6.m5.q12', 'hist.c6.m5', 'mc', 'A cidade de Palmas, capital do Tocantins, tem como característica:', null, '["Avenidas gigantes e muito espaçadas, traçado em quadrículas e muitas áreas verdes.","Ruas estreitas que cresceram sem planejamento.","Ter sido reformada pelos holandeses.","Ter sido a primeira cidade planejada do Brasil, em 1549."]'::jsonb, 0, null, 'Palmas foi uma das últimas grandes experiências de planejamento urbano no Brasil, com traçado em quadrículas para facilitar as funções da cidade.', 'L3 p.27', 2, true),
  ('hist.c6.m5.q13', 'hist.c6.m5', 'mc', 'Por que Curitiba ficou conhecida como "capital ecológica"?', null, '["Por causa dos ônibus biarticulados, das canaletas exclusivas, do programa de coleta de lixo reciclável e do grande número de parques e áreas verdes.","Porque foi planejada antes de ser construída.","Porque foi a primeira cidade fundada no Brasil.","Porque nela fica o maior jardim botânico do país."]'::jsonb, 0, null, 'Curitiba não foi planejada, mas passou por um processo de reestruturação entre os anos 70 e 90 que lhe deu esse título.', 'L3 p.27', 2, true),
  ('hist.c6.m5.q14', 'hist.c6.m5', 'assoc', 'Ligue cada palavra ao seu significado:', null, null, null, '[["Traçado","Organização, desenho de um espaço urbano"],["Biarticulado","Ônibus maior, com duas articulações"],["Canaleta","Via onde só os ônibus podem circular"],["Art Déco","Arte decorativa europeia presente no cinema e na arquitetura"]]'::jsonb, 'Essas palavras aparecem no boxe de vocabulário do livro, junto dos textos sobre Palmas, Curitiba e Goiânia.', 'L3 p.26 e p.27', 2, true),
  ('hist.c6.m6.q01', 'hist.c6.m6', 'mc', 'Sinop é uma cidade:', 'Sinop é uma cidade fundada em 1974 no Mato Grosso. A cidade foi pensada para ser ocupada por pessoas de outros estados do Brasil. Para isso, seu traçado urbano foi pensado e desenvolvido pelo engenheiro civil Roberto Brandão, para, então, ser construída. Atualmente, a cidade conta com características como ruas regulares e avenidas de até 50 metros de largura.', '["Planejada, porque foi pensada e desenhada por um engenheiro antes de ser construída.","Espontânea, porque cresceu a partir de um povoado.","Espontânea, porque foi fundada há pouco tempo.","Planejada, porque foi reformada depois de pronta."]'::jsonb, 0, null, 'O traçado urbano de Sinop foi pensado antes da construção, com ruas regulares e avenidas largas. Isso é característica de cidade planejada.', 'L3 p.30, atividade 2a', 2, true),
  ('hist.c6.m6.q02', 'hist.c6.m6', 'mc', 'Manaus é uma cidade:', 'Manaus, no Amazonas, surgiu de um povoado fundado em 1669. Esse povoado se formou ao redor da fortaleza de São José do Rio Negro. Lentamente, o povoado cresceu e tornou-se uma vila. No ano de 1848, o intenso comércio transformou a vila em uma cidade.', '["Espontânea, porque foi crescendo aos poucos: povoado, depois vila e depois cidade.","Planejada, porque foi construída em volta de uma fortaleza.","Planejada, porque tem avenidas largas.","Espontânea, porque foi projetada por um engenheiro."]'::jsonb, 0, null, 'Manaus nasceu de um povoado que virou vila e depois cidade, sem projeto anterior. Por isso é espontânea.', 'L3 p.30, atividade 2b', 2, true),
  ('hist.c6.m6.q03', 'hist.c6.m6', 'mc', 'Para que serviu a fortaleza de São José do Rio Negro, ao redor da qual Manaus surgiu?', null, '["Para proteger a região da invasão de povos estrangeiros.","Para guardar a produção de café.","Para servir de moradia ao rei de Portugal.","Para abrigar o Governo Geral do Brasil."]'::jsonb, 0, null, 'A fortaleza foi construída para proteger a região da invasão de povos estrangeiros.', 'L3 p.30, atividade 2b', 2, true),
  ('hist.c6.m6.q04', 'hist.c6.m6', 'mc', 'Florianópolis é uma cidade:', 'Florianópolis, em Santa Catarina, teve como primeiros habitantes os indígenas tupis-guaranis, que praticavam a agricultura e a pesca. Por volta de 1675, um viajante e explorador chamado Francisco Dias Velho, seus familiares e agregados chegaram à região, dando início a um povoado. Assim, o povoado se tornou uma vila e, com o passar do tempo, transformou-se em cidade.', '["Espontânea, porque se formou aos poucos a partir de um povoado.","Planejada, porque foi pensada por um explorador.","Planejada, porque seus primeiros habitantes eram indígenas.","Espontânea, porque tem ruas regulares e avenidas largas."]'::jsonb, 0, null, 'O povoado iniciado por Francisco Dias Velho cresceu, virou vila e depois cidade. Isso é crescimento espontâneo.', 'L3 p.31, atividade 2c', 2, true),
  ('hist.c6.m6.q05', 'hist.c6.m6', 'mc', 'Maringá é uma cidade:', 'Maringá se localiza no Paraná e foi inaugurada em 1947. O projeto da cidade foi criado pelo engenheiro Jorge de Macedo. Em seu desenho, foram considerados os espaços que deveriam se tornar parques, praças, ruas e avenidas. As áreas onde havia árvores e vegetação também foram pensadas e preservadas no projeto.', '["Planejada, porque um engenheiro fez o projeto com parques, praças, ruas e avenidas antes da cidade existir.","Espontânea, porque começou com um povoado de agricultores.","Espontânea, porque foi inaugurada em 1947.","Planejada, porque foi reformada nos anos 70."]'::jsonb, 0, null, 'O projeto de Maringá foi criado pelo engenheiro Jorge de Macedo antes da cidade ser construída, já pensando nos parques, praças, ruas e avenidas.', 'L3 p.31, atividade 2d', 2, true),
  ('hist.c6.m6.q06', 'hist.c6.m6', 'mc', 'O que pode acontecer quando uma cidade não é planejada e não passa por reformas urbanas ao longo de sua história?', null, '["Ela pode crescer de maneira improvisada e ter problemas urbanos e sociais, como aconteceu nas cidades ao redor de Brasília.","Ela cresce com ruas sempre largas e organizadas.","Ela nunca aumenta de tamanho.","Ela se transforma automaticamente em capital."]'::jsonb, 0, null, 'Sem planejamento e sem reformas, a cidade cresce de forma improvisada, o que provoca problemas urbanos e sociais.', 'L3 p.25 e p.28, atividade 3', 2, true),
  ('hist.c6.m6.q07', 'hist.c6.m6', 'vf', 'Todas as cidades brasileiras surgiram a partir de povoados.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Nem todas: algumas foram projetadas antes de serem construídas. Essas são as cidades planejadas.', 'L3 p.24 e p.35', 2, true),
  ('hist.c6.m6.q08', 'hist.c6.m6', 'assoc', 'Ligue cada cidade ao tipo a que ela pertence:', null, null, null, '[["Sinop (MT)","Planejada"],["Manaus (AM)","Espontânea"],["Maringá (PR)","Planejada"],["Florianópolis (SC)","Espontânea"]]'::jsonb, 'Sinop e Maringá tiveram projeto antes da construção. Manaus e Florianópolis nasceram de povoados que foram crescendo.', 'L3 p.30 e p.31', 2, true),
  ('hist.c6.m6.q09', 'hist.c6.m6', 'assoc', 'Revisão geral: ligue cada cidade à sua marca na história:', null, null, null, '[["São Vicente","Primeira vila do Brasil, fundada em 1532"],["Brasília","Planejada em formato de avião para ser a capital"],["Salvador","Cidade-fortaleza planejada em 1549"],["Goiânia","Primeira cidade planejada do século 20"]]'::jsonb, 'Guarde bem essas datas e características: elas aparecem muito nas provas.', 'L3 p.16, p.24, p.26', 2, true),
  ('hist.c6.m6.q10', 'hist.c6.m6', 'mc', 'Complete: as cidades que se formaram a partir de povoados que viraram vilas e depois cidades são chamadas de ______, e as que foram projetadas antes de serem construídas são chamadas de ______.', null, '["espontâneas / planejadas","planejadas / espontâneas","antigas / modernas","reformadas / fundadas"]'::jsonb, 0, null, 'Espontâneas: cresceram sozinhas. Planejadas: foram projetadas antes.', 'L3 p.34 e p.35', 2, true),
  ('geo.c6.m1.q01', 'geo.c6.m1', 'mc', 'O que são recursos naturais?', null, '["São os elementos existentes na natureza, usados para fabricar produtos e importantes para a sobrevivência dos seres vivos.","São os produtos que compramos nas lojas.","São os materiais que descartamos no lixo.","São as máquinas usadas nas indústrias."]'::jsonb, 0, null, 'As roupas, os aparelhos eletrônicos e outros objetos são produzidos a partir da exploração dos recursos naturais, ou seja, dos elementos existentes na natureza.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q02', 'geo.c6.m1', 'mc', 'Quais são exemplos de recursos naturais citados no livro?', null, '["A luz e o calor do Sol, o ar, a água, o solo e as plantas.","O plástico, o vidro e o papel.","As indústrias, os caminhões e as máquinas.","O suco, a camiseta e a cadeira."]'::jsonb, 0, null, 'Esses recursos servem para fabricar produtos e também são importantes para a sobrevivência dos seres vivos no planeta Terra.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q03', 'geo.c6.m1', 'mc', 'Para que serve a luz do Sol?', null, '["É fundamental para o desenvolvimento das plantas, que são usadas na produção de alimentos e madeira.","Serve apenas para as pessoas respirarem.","Serve para matar a sede das pessoas.","Serve para produzir o aço e o vidro."]'::jsonb, 0, null, 'A luz do Sol faz as plantas se desenvolverem. Já o calor do Sol é responsável por aquecer nosso planeta.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q04', 'geo.c6.m1', 'mc', 'Por que o ar é um recurso natural importante?', null, '["Porque as pessoas e vários animais precisam dele para respirar e, quando se movimenta, forma os ventos, que podem gerar energia elétrica.","Porque dele são extraídos o arroz e o feijão.","Porque ele é usado para fabricar vidro.","Porque ele serve para regar as plantas."]'::jsonb, 0, null, 'O ar serve para respirar e, em movimento, forma os ventos, usados para gerar energia elétrica.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q05', 'geo.c6.m1', 'mc', 'O que é plantado e o que é extraído do solo?', null, '["Nele são plantados alimentos como arroz, feijão, legumes e frutas; dele também são extraídos materiais usados na produção do aço e do vidro.","Dele só é extraído o petróleo.","Nele só é plantada a melancia.","Dele são extraídos os ventos e a luz."]'::jsonb, 0, null, 'O solo serve para o cultivo de alimentos e também fornece materiais para produzir aço e vidro.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q06', 'geo.c6.m1', 'mc', 'Segundo o livro, para que serve a água?', null, '["Para matar a sede, para fazer vários produtos, como os sucos, e também para produzir energia elétrica.","Somente para matar a sede das pessoas.","Somente para regar as plantas.","Para produzir o vidro e o aço."]'::jsonb, 0, null, 'Assim como o vento, o calor e a luz do Sol, a água pode ser usada para produzir energia elétrica.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q07', 'geo.c6.m1', 'mc', 'Que materiais são extraídos das plantas?', null, '["Materiais relacionados à produção de alimentos, de móveis e de borracha.","Materiais para produzir o aço.","Materiais para produzir o vidro.","Somente a água dos sucos."]'::jsonb, 0, null, 'Das plantas são extraídos diversos materiais, ligados à produção de alimentos, móveis e borracha.', 'L3 p.88', 2, true),
  ('geo.c6.m1.q08', 'geo.c6.m1', 'assoc', 'Relacione cada recurso natural à sua função:', null, null, null, '[["Sol","Sua luz e seu calor podem ser usados para produzir energia elétrica"],["Ar","É importante para que as pessoas possam respirar"],["Água","Serve para beber e para fazer produtos"],["Solo","É usado no cultivo de diferentes tipos de plantas"]]'::jsonb, 'Cuidado para não trocar Sol e solo! O Sol dá luz e calor; o solo é a terra onde plantamos.', 'L3 p.91, atividade 1', 2, true),
  ('geo.c6.m1.q09', 'geo.c6.m1', 'vf', 'O solo é o recurso natural que serve para as pessoas respirarem.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Quem serve para respirar é o ar. O solo é usado no cultivo de plantas.', 'L3 p.88 e p.91', 2, true),
  ('geo.c6.m1.q10', 'geo.c6.m1', 'mc', 'O Garfinho, do filme Toy Story 4, foi feito com um garfo descartável, madeira e tecido. O que esses itens têm em comum?', null, '["Todos foram produzidos a partir de recursos disponíveis na natureza.","Todos são feitos de plástico.","Todos foram comprados em uma loja.","Nenhum deles pode ser reutilizado."]'::jsonb, 0, null, 'Bonnie criou o Garfinho a partir de objetos que iriam para o lixo — e todos eles vieram de recursos da natureza.', 'L3 p.84 e p.85', 2, true),
  ('geo.c6.m1.q11', 'geo.c6.m1', 'vf', 'Só a água pode ser usada para produzir energia elétrica.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! O vento, o calor e a luz do Sol também podem ser usados para produzir energia elétrica.', 'L3 p.88', 2, true),
  ('geo.c6.m2.q01', 'geo.c6.m2', 'mc', 'O que é uma matéria-prima?', null, '["É o recurso natural utilizado na fabricação de um produto.","É o produto pronto que compramos.","É o lixo que sobra da fabricação.","É a máquina usada na indústria."]'::jsonb, 0, null, 'Quando um recurso natural é utilizado na fabricação de um produto, ele recebe o nome de matéria-prima.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q02', 'geo.c6.m2', 'vf', 'Cada produto só pode ser feito com uma única matéria-prima.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Na produção de um objeto ou de uma máquina, mais de uma matéria-prima pode ser usada — como acontece no carro.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q03', 'geo.c6.m2', 'mc', 'Do que é produzido o plástico usado em várias partes dos carros?', null, '["Da mistura de petróleo com outros materiais.","Da areia levada a fornos quentes.","Do látex extraído da seringueira.","Do minério de ferro retirado das rochas."]'::jsonb, 0, null, 'O plástico é produzido misturando petróleo e outros materiais.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q04', 'geo.c6.m2', 'mc', 'Qual é o principal material utilizado para produzir o vidro das janelas dos carros?', null, '["A areia, um recurso natural.","O algodão.","O ferro.","A borracha natural."]'::jsonb, 0, null, 'Para que os vidros sejam fabricados, os materiais usados são misturados e levados a fornos com altas temperaturas.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q05', 'geo.c6.m2', 'mc', 'Por que o algodão é considerado um recurso natural?', null, '["Por ser uma planta. Com ele são feitos tecidos e também as roupas que vestimos.","Por ser feito nas indústrias.","Por ser retirado das rochas.","Por ser extraído do fundo do mar."]'::jsonb, 0, null, 'O algodão é uma planta. Em muitos carros, os bancos são cobertos de tecido feito de algodão.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q06', 'geo.c6.m2', 'mc', 'Onde o petróleo é encontrado e para que mais ele serve?', null, '["É encontrado no fundo da terra ou do mar e também é usado na fabricação de combustíveis para os automóveis.","É encontrado nas rochas e serve para fazer vidro.","É extraído das árvores e serve para fazer pneus.","É retirado do solo e serve para fazer alimentos."]'::jsonb, 0, null, 'O petróleo é um recurso natural encontrado no fundo da terra ou do mar. Além do plástico, dele são feitos combustíveis.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q07', 'geo.c6.m2', 'mc', 'De onde vem o minério de ferro, usado na produção do aço da carroceria dos carros?', null, '["É retirado das rochas que existem na natureza.","É produzido dentro das indústrias, sem usar a natureza.","É extraído da seringueira.","É feito a partir da areia."]'::jsonb, 0, null, 'O minério de ferro é um recurso natural retirado das rochas. O aço é feito com base na mistura de elementos naturais, como o ferro.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q08', 'geo.c6.m2', 'mc', 'Os pneus são feitos de vários materiais. Um deles é a borracha natural, que é feita de:', null, '["látex, um material extraído de uma árvore chamada seringueira.","petróleo retirado do fundo do mar.","areia levada a fornos com altas temperaturas.","algodão colhido nas plantações."]'::jsonb, 0, null, 'A borracha natural vem do látex, extraído da seringueira.', 'L3 p.89', 2, true),
  ('geo.c6.m2.q09', 'geo.c6.m2', 'assoc', 'Registre qual matéria-prima é utilizada na fabricação de cada produto:', null, null, null, '[["Camiseta","Algodão"],["Geleia","Morango"],["Pães","Trigo"],["Cadeira","Madeira"]]'::jsonb, 'Cada produto vem de uma matéria-prima que existe na natureza.', 'L3 p.91, atividade 2', 2, true),
  ('geo.c6.m2.q10', 'geo.c6.m2', 'assoc', 'Ligue cada parte do carro à sua matéria-prima:', null, null, null, '[["Janelas","Vidro, feito de areia"],["Pneus","Borracha natural, do látex"],["Carroceria","Aço, feito com ferro"],["Bancos","Tecido de algodão"]]'::jsonb, 'Um único carro usa várias matérias-primas diferentes, todas vindas da natureza.', 'L3 p.89', 2, true),
  ('geo.c6.m3.q01', 'geo.c6.m3', 'mc', 'O que acontece com as matérias-primas antes de se tornarem os produtos que consumimos?', null, '["Elas passam por várias transformações.","Elas vão direto para as lojas, sem mudar.","Elas viram lixo.","Elas voltam para a natureza."]'::jsonb, 0, null, 'As matérias-primas podem passar por várias transformações antes de se tornarem os produtos consumidos pelas pessoas.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q02', 'geo.c6.m3', 'mc', 'No exemplo do livro, qual é a matéria-prima e qual é o produto?', null, '["A matéria-prima é a laranja e o produto é o suco.","A matéria-prima é o suco e o produto é a laranja.","A matéria-prima é a máquina e o produto é a fruta.","A matéria-prima é o copo e o produto é a laranja."]'::jsonb, 0, null, 'Tanto no formato artesanal quanto no industrial, a matéria-prima é a laranja e o produto é o suco.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q03', 'geo.c6.m3', 'mc', 'Quando acontece a produção artesanal?', null, '["Quando a transformação da matéria-prima é feita manualmente ou com ferramentas que dependem do trabalho manual.","Quando a transformação é feita por grandes máquinas nas indústrias.","Quando o produto é vendido em muitas lojas.","Quando a matéria-prima vem de outro país."]'::jsonb, 0, null, 'Na produção artesanal o trabalho é manual, feito com as mãos ou com ferramentas simples.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q04', 'geo.c6.m3', 'mc', 'Na produção artesanal, quem costuma cuidar das etapas do processo?', null, '["A mesma pessoa pode ficar responsável por todas as etapas.","Cada etapa fica com um grupo diferente de máquinas.","Ninguém participa: tudo é automático.","Só os donos das indústrias."]'::jsonb, 0, null, 'Na forma artesanal, a mesma pessoa pode fazer todas as etapas e costumam ser produzidas pequenas quantidades do mesmo item.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q05', 'geo.c6.m3', 'mc', 'Como funciona a produção industrial?', null, '["A transformação é feita nas indústrias, com a produção dividida em várias etapas, usando máquinas e tecnologias.","A transformação é feita à mão, em casa.","Cada produto é feito por uma pessoa só, do começo ao fim.","São produzidas pequenas quantidades de cada item."]'::jsonb, 0, null, 'Na produção industrial, cada etapa fica sob a responsabilidade de um grupo de pessoas e/ou máquinas.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q06', 'geo.c6.m3', 'mc', 'Qual é a vantagem da produção industrial em relação à artesanal?', null, '["Ela consegue fabricar vários itens por vez, de maneira mais rápida.","Ela usa menos máquinas.","Ela produz quantidades menores.","Ela não precisa de matéria-prima."]'::jsonb, 0, null, 'A produção industrial fabrica vários itens de uma só vez e mais rapidamente que a artesanal.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q07', 'geo.c6.m3', 'vf', 'Um suco feito em casa, com as laranjas espremidas à mão, é um exemplo de produção artesanal.', null, '["Verdadeiro","Falso"]'::jsonb, 0, null, 'Verdadeiro! Quando a transformação é manual, a produção é artesanal.', 'L3 p.90', 2, true),
  ('geo.c6.m3.q08', 'geo.c6.m3', 'mc', 'O que se pode dizer sobre a forma como Bruno consome tênis?', 'Bruno adora usar tênis novos. Todos os meses ele vai à loja comprar novos modelos para não perder nenhum lançamento. Ao todo, já possui trinta pares de tênis e costuma usar apenas o modelo que comprou por último, deixando os outros guardados no armário.', '["Ele consome muito mais do que precisa, comprando produtos que nem chega a usar.","Ele consome de forma consciente, porque guarda tudo com cuidado.","Ele ajuda a natureza, porque compra sempre novidades.","Ele não gera nenhum impacto na natureza."]'::jsonb, 0, null, 'Consumir mais produtos do que o necessário faz com que mais recursos naturais sejam usados para fabricá-los.', 'L3 p.92, atividade 4a', 2, true),
  ('geo.c6.m3.q09', 'geo.c6.m3', 'mc', 'O que Bruno poderia fazer com os tênis que não usa mais, ajudando a preservar a natureza?', null, '["Doar ou passar adiante os pares que estão guardados, para que outras pessoas os usem.","Jogar todos no lixo comum.","Comprar mais pares para completar a coleção.","Guardar todos para sempre no armário."]'::jsonb, 0, null, 'Reaproveitar o que já existe evita a fabricação de novos produtos e, assim, economiza recursos naturais.', 'L3 p.92, atividade 4b', 2, true),
  ('geo.c6.m4.q01', 'geo.c6.m4', 'mc', 'O que costumamos chamar de lixo?', null, '["Os materiais que geralmente descartamos, como restos de comida, cascas de alimentos e folhas de papel.","Apenas as embalagens de plástico.","Somente aquilo que vai para o aterro sanitário.","Os produtos novos que compramos."]'::jsonb, 0, null, 'Fazemos o descarte de diversos materiais diariamente: restos de comida, cascas, papéis e pedaços de lápis, por exemplo.', 'L3 p.93', 2, true),
  ('geo.c6.m4.q02', 'geo.c6.m4', 'vf', 'O único destino possível para os materiais que descartamos é a lixeira.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Muitos materiais podem ser reaproveitados ou reutilizados antes de virarem lixo.', 'L3 p.93', 2, true),
  ('geo.c6.m4.q03', 'geo.c6.m4', 'mc', 'O que pode ser feito com as cascas de frutas em vez de jogá-las fora?', null, '["Elas podem ser reaproveitadas em receitas, como geleias, tortas, doces e bolos.","Elas só podem ir para o lixão.","Elas podem ser transformadas em vidro.","Elas devem ser guardadas no armário."]'::jsonb, 0, null, 'As cascas de frutas podem virar receitas deliciosas em vez de virar lixo.', 'L3 p.93', 2, true),
  ('geo.c6.m4.q04', 'geo.c6.m4', 'mc', 'O que se pode fazer com embalagens plásticas e de vidro vazias?', null, '["Depois de higienizadas, elas podem ser reaproveitadas para armazenar outros produtos e elementos.","Elas devem sempre ir para o lixão.","Elas não podem ser reaproveitadas de jeito nenhum.","Elas devem ser queimadas em casa."]'::jsonb, 0, null, 'Depois de bem lavadas, as embalagens podem guardar outras coisas — até plantas!', 'L3 p.93', 2, true),
  ('geo.c6.m4.q05', 'geo.c6.m4', 'mc', 'As sacolas plásticas usadas no transporte de produtos:', null, '["podem ser reutilizadas em diversas outras situações.","só servem uma única vez.","são recursos naturais.","devem ser descartadas em um lixão."]'::jsonb, 0, null, 'Reutilizar sacolas é uma forma simples de gerar menos lixo.', 'L3 p.93', 2, true),
  ('geo.c6.m4.q06', 'geo.c6.m4', 'mc', 'O que é importante pensar antes de jogar qualquer material na lixeira?', null, '["Se aquilo realmente precisa virar lixo ou se pode ser reutilizado em outro momento.","Se a lixeira está cheia.","Se o material é bonito.","Se alguém está olhando."]'::jsonb, 0, null, 'Existem diversas maneiras de usar os materiais que sobram das atividades do dia a dia.', 'L3 p.93', 2, true),
  ('geo.c6.m4.q07', 'geo.c6.m4', 'mc', 'Por que consumir menos produtos ajuda a natureza?', null, '["Porque assim menos recursos naturais precisam ser explorados e menos lixo é gerado.","Porque as indústrias produzem mais rápido.","Porque os produtos ficam mais caros.","Porque o lixo desaparece sozinho."]'::jsonb, 0, null, 'Todo produto é feito a partir de recursos naturais. Consumindo com consciência, usamos menos a natureza e geramos menos lixo.', 'L3 p.88, p.92 e p.93', 2, true),
  ('geo.c6.m5.q01', 'geo.c6.m5', 'mc', 'Como começa o caminho do lixo na maior parte dos municípios brasileiros?', null, '["Pela coleta: caminhões passam nas ruas e recolhem os lixos de casas, restaurantes, escolas etc.","Pela reciclagem nas fábricas.","Pelo aterro sanitário.","Pela cooperativa de catadores."]'::jsonb, 0, null, 'Tudo começa na coleta do lixo. Muitas vezes o lixo coletado é todo misturado no mesmo caminhão.', 'L3 p.94', 2, true),
  ('geo.c6.m5.q02', 'geo.c6.m5', 'mc', 'O que é a coleta seletiva de lixo?', null, '["Um serviço em que um caminhão passa em um dia específico da semana só para recolher os materiais recicláveis.","Um serviço que recolhe todo o lixo misturado.","Um lugar a céu aberto onde o lixo é jogado.","Uma fábrica que produz novos objetos."]'::jsonb, 0, null, 'Para a coleta seletiva funcionar, as pessoas devem separar os recicláveis dos restos de alimentos e de outros tipos de lixo.', 'L3 p.94', 2, true),
  ('geo.c6.m5.q03', 'geo.c6.m5', 'mc', 'Quais materiais são recolhidos pela coleta seletiva?', null, '["Papel, plástico, metal e vidro.","Restos de comida e cascas de frutas.","Somente papel e papelão.","Terra, areia e pedras."]'::jsonb, 0, null, 'Esses são os materiais recicláveis, que podem ser utilizados para produzir novos objetos.', 'L3 p.94', 2, true),
  ('geo.c6.m5.q04', 'geo.c6.m5', 'mc', 'O que significa dizer que um material é reciclável?', null, '["Que ele pode ser utilizado para produzir novos objetos.","Que ele não pode mais ser usado.","Que ele precisa ir para o lixão.","Que ele é um recurso natural."]'::jsonb, 0, null, 'Reciclável: que pode ser utilizado para produzir novos objetos.', 'L3 p.94', 2, true),
  ('geo.c6.m5.q05', 'geo.c6.m5', 'mc', 'O que é um lixão?', null, '["Um lugar proibido por lei, onde o lixo é descartado a céu aberto, ficando exposto.","O lugar correto para descartar o lixo.","Uma fábrica de reciclagem.","Um caminhão que faz a coleta seletiva."]'::jsonb, 0, null, 'Nos lixões, os materiais são descartados a céu aberto. Por isso esses locais são proibidos por lei.', 'L3 p.95', 2, true),
  ('geo.c6.m5.q06', 'geo.c6.m5', 'mc', 'Quais problemas o lixão pode causar?', null, '["Danos à natureza, como a contaminação do solo, e danos à saúde das pessoas, por acumular seres transmissores de doenças.","Nenhum problema, porque o lixo fica bem guardado.","Apenas mau cheiro, sem nenhum outro risco.","Só problemas para os animais, nunca para as pessoas."]'::jsonb, 0, null, 'Os lixões contaminam a água e o solo e poluem o ar, afetando diretamente a saúde de muitas pessoas.', 'L3 p.95 e p.96, atividade 2', 2, true),
  ('geo.c6.m5.q07', 'geo.c6.m5', 'mc', 'Por que o aterro sanitário é um lugar correto para descartar o lixo?', null, '["Porque é preparado para evitar a poluição do solo e da água, e o lixo é coberto com uma camada de areia.","Porque o lixo fica a céu aberto.","Porque o lixo é jogado em qualquer lugar.","Porque nele o lixo é queimado."]'::jsonb, 0, null, 'Como o lixo é coberto, o mau cheiro é menor e há menos animais que podem causar doenças nas pessoas.', 'L3 p.95', 2, true),
  ('geo.c6.m5.q08', 'geo.c6.m5', 'mc', 'Para onde vão os materiais recicláveis depois de coletados?', null, '["Para centrais públicas de triagem ou cooperativas de catadores, onde são separados e depois enviados a fábricas para virarem outros produtos.","Direto para o lixão.","Para os aterros sanitários, junto com o resto do lixo.","Eles ficam guardados nos caminhões."]'::jsonb, 0, null, 'Nesses lugares os materiais são separados de acordo com suas características e depois transformados em novos produtos.', 'L3 p.95', 2, true),
  ('geo.c6.m5.q09', 'geo.c6.m5', 'assoc', 'Associe os lugares de destino do lixo às afirmativas sobre eles:', null, null, null, '[["Aterro sanitário","Local preparado para receber o lixo com menor possibilidade de poluição dos recursos naturais"],["Central de triagem ou cooperativa","Local em que o material reciclável é separado e depois encaminhado às indústrias"],["Lixão","Local a céu aberto, proibido por lei"]]'::jsonb, 'Aterro sanitário e lixão não são a mesma coisa: o aterro é preparado para proteger o solo e a água; o lixão deixa tudo exposto.', 'L3 p.95 e p.97, atividade 3', 2, true),
  ('geo.c6.m5.q10', 'geo.c6.m5', 'vf', 'Os lixões são permitidos por lei no Brasil.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! Locais desse tipo são proibidos por lei, pois o lixo fica exposto a céu aberto.', 'L3 p.95', 2, true),
  ('geo.c7.m1.q01', 'geo.c7.m1', 'mc', 'Quantos litros de água, em média, um brasileiro consome por dia em suas atividades?', null, '["200 litros — a mesma quantidade que um elefante bebe diariamente.","2 litros, só para beber.","12 litros.","1000 litros."]'::jsonb, 0, null, 'Os brasileiros consomem, em média, 200 litros de água por dia — o mesmo que um elefante bebe por dia.', 'L3 p.106', 2, true),
  ('geo.c7.m1.q02', 'geo.c7.m1', 'mc', 'Por que é tão importante lavar as mãos com água e sabão?', null, '["Porque isso evita que seres causadores de doenças entrem em nosso corpo e prejudiquem nossa saúde.","Porque assim gastamos mais água.","Porque deixa as mãos perfumadas.","Porque as mãos ficam mais fortes."]'::jsonb, 0, null, 'É importante lavar as mãos depois de brincar, antes das refeições e logo após usar o banheiro.', 'L3 p.110', 2, true),
  ('geo.c7.m1.q03', 'geo.c7.m1', 'mc', 'Quantos litros podem ser gastos se a torneira ficar aberta durante um minuto de lavagem das mãos?', null, '["Pouco mais de 2 litros.","135 litros.","279 litros.","Menos de meio litro."]'::jsonb, 0, null, 'Em um minuto com a torneira aberta, podem ser gastos pouco mais de 2 litros de água.', 'L3 p.110', 2, true),
  ('geo.c7.m1.q04', 'geo.c7.m1', 'mc', 'Escovando os dentes com a torneira meio aberta durante 5 minutos, quanto se gasta? E fechando a torneira e usando um copo?', null, '["12 litros com a torneira aberta e menos de 1 litro com a torneira fechada.","2 litros com a torneira aberta e 1 litro com ela fechada.","135 litros com a torneira aberta e 45 litros com ela fechada.","22 litros com a torneira aberta e 12 litros com ela fechada."]'::jsonb, 0, null, 'Molhar a escova, fechar a torneira enquanto escova e enxaguar a boca com um copo economiza muita água.', 'L3 p.110', 2, true),
  ('geo.c7.m1.q05', 'geo.c7.m1', 'mc', 'Durante 15 minutos de banho podem ser gastos 135 litros. O que fazer para reduzir esse gasto?', null, '["Fechar o chuveiro ao se ensaboar: o gasto cai para 45 litros.","Deixar de tomar banho.","Tomar banho com a torneira da pia aberta.","Aumentar o tempo do banho."]'::jsonb, 0, null, 'Fechar o chuveiro na hora de se ensaboar reduz o gasto de 135 para 45 litros. Deixar de tomar banho não é solução: a higiene é importante para a saúde.', 'L3 p.110 e p.115', 2, true),
  ('geo.c7.m1.q06', 'geo.c7.m1', 'mc', 'Sobre a lavagem de roupas, é correto afirmar que:', null, '["lavar na pia com a torneira aberta por 15 minutos pode gastar até 279 litros; na máquina com até 5 quilos de roupa, o gasto é de 135 litros por lavagem.","lavar na pia gasta sempre menos água que a máquina.","a máquina não usa água.","lavar roupa gasta apenas 5 litros."]'::jsonb, 0, null, 'O ideal é colocar sempre a quantidade máxima de roupas que a máquina suporta.', 'L3 p.110', 2, true),
  ('geo.c7.m1.q07', 'geo.c7.m1', 'mc', 'Quanta água se gasta lavando louça com a torneira aberta, e qual é a dica para evitar o desperdício?', null, '["117 litros a cada 15 minutos; a dica é ensaboar os utensílios com a torneira fechada.","22 litros a cada 15 minutos; a dica é lavar tudo de uma vez.","5 litros por dia; a dica é usar mais detergente.","180 litros por minuto; a dica é usar um regador."]'::jsonb, 0, null, 'A média para a lavagem de banheiros é de 22 litros; já a lavagem de louça com a torneira aberta gasta 117 litros a cada 15 minutos.', 'L3 p.111', 2, true),
  ('geo.c7.m1.q08', 'geo.c7.m1', 'mc', 'Quanta água um adulto deve beber, em média, por dia para se manter saudável?', null, '["Cerca de 2 litros.","Cerca de 20 litros.","Cerca de 200 litros.","Menos de meio litro."]'::jsonb, 0, null, 'A quantidade pode variar de acordo com as necessidades de cada pessoa, mas a média para um adulto é de 2 litros por dia.', 'L3 p.111', 2, true),
  ('geo.c7.m1.q09', 'geo.c7.m1', 'mc', 'Quantos litros de água são necessários para cozinhar um pacote de macarrão?', null, '["5 litros.","2 litros.","117 litros.","180 litros."]'::jsonb, 0, null, 'A água também é necessária para preparar alimentos e bebidas, e a quantidade varia conforme o alimento.', 'L3 p.111', 2, true),
  ('geo.c7.m1.q10', 'geo.c7.m1', 'mc', 'Ao regar as plantas com mangueira, são gastos cerca de 180 litros a cada 10 minutos. Qual é a dica do livro para gastar menos?', null, '["Usar um regador para molhar as plantas.","Regar as plantas duas vezes por dia.","Deixar a mangueira ligada por mais tempo.","Não regar mais as plantas."]'::jsonb, 0, null, 'Como todos os seres vivos, as plantas precisam de água — mas dá para regar sem desperdiçar, usando um regador.', 'L3 p.111', 2, true),
  ('geo.c7.m1.q11', 'geo.c7.m1', 'assoc', 'Ligue cada atividade à quantidade de água que ela pode gastar:', null, null, null, '[["Banho de 15 minutos","135 litros"],["Escovar os dentes com a torneira meio aberta por 5 minutos","12 litros"],["Regar as plantas por 10 minutos","180 litros"],["Lavar louça por 15 minutos com a torneira aberta","117 litros"]]'::jsonb, 'Guardar esses números ajuda a perceber quanta água pode ser economizada com pequenas atitudes.', 'L3 p.110 e p.111', 2, true),
  ('geo.c7.m2.q01', 'geo.c7.m2', 'mc', 'O que significa usar a água de maneira indireta?', null, '["É quando consumimos um produto que precisou de água para ser fabricado.","É quando bebemos água direto da torneira.","É quando tomamos banho.","É quando regamos as plantas."]'::jsonb, 0, null, 'A água é importante para fabricar alimentos, remédios, roupas, automóveis e outros produtos. Quando consumimos esses produtos, usamos a água de maneira indireta.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q02', 'geo.c7.m2', 'mc', 'Quantos litros de água são usados para fabricar uma folha de papel?', null, '["10 litros, o que corresponde a cerca de 50 copos d''água.","2 litros.","2700 litros.","400 000 litros."]'::jsonb, 0, null, 'Uma única folha de papel precisa de 10 litros de água — mais ou menos 50 copos.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q03', 'geo.c7.m2', 'mc', 'Quantos litros de água são usados para fabricar uma camiseta de algodão?', null, '["2700 litros, mais ou menos 135 galões d''água.","10 litros.","135 litros.","15 500 litros."]'::jsonb, 0, null, 'Fabricar uma camiseta de algodão gasta 2700 litros de água.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q04', 'geo.c7.m2', 'mc', 'E para produzir um quilo de carne bovina, quanta água é necessária?', null, '["15 500 litros, quantidade que poderia encher uma piscina pequena.","5 litros.","200 litros.","2700 litros."]'::jsonb, 0, null, 'Produzir um quilo de carne bovina usa 15 500 litros de água.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q05', 'geo.c7.m2', 'mc', 'Para fabricar um automóvel são usados 400 000 litros de água. Essa quantidade daria para:', null, '["abastecer, aproximadamente, a casa de 40 famílias de três pessoas por um mês.","encher um copo d''água.","lavar uma louça.","regar uma planta por 10 minutos."]'::jsonb, 0, null, 'É muita água! Por isso é importante consumir com consciência.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q06', 'geo.c7.m2', 'mc', 'O que quer dizer a palavra diluição?', null, '["Ação de misturar água a outra substância.","Ação de separar o lixo reciclável.","Ação de regar as plantas.","Ação de ferver a água."]'::jsonb, 0, null, 'Nas indústrias, a água é usada como matéria-prima, na limpeza de máquinas e na diluição de materiais.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q07', 'geo.c7.m2', 'mc', 'O que são as usinas hidrelétricas?', null, '["Locais onde a água é usada para produzir eletricidade; boa parte da energia elétrica do Brasil vem delas.","Fábricas que produzem água potável.","Locais onde o lixo é reciclado.","Máquinas que irrigam as plantações."]'::jsonb, 0, null, 'A usina hidrelétrica de Itaipu, entre o Brasil e o Paraguai, é considerada uma das maiores do mundo.', 'L3 p.112', 2, true),
  ('geo.c7.m2.q08', 'geo.c7.m2', 'mc', 'Como funciona a irrigação por gotejamento?', null, '["A água passa por mangueiras com pequenos furos e sai por eles, molhando o solo bem perto de onde as plantas estão.","Grandes máquinas borrifam água por todo o terreno.","A chuva molha sozinha a plantação.","A água é levada em baldes até cada planta."]'::jsonb, 0, null, 'O gotejamento leva a água direto para perto das plantas, por mangueiras furadas.', 'L3 p.113', 2, true),
  ('geo.c7.m2.q09', 'geo.c7.m2', 'mc', 'E a irrigação por aspersão?', null, '["É usada em plantações maiores, com grandes máquinas que borrifam água por todo o terreno.","É feita com mangueiras de pequenos furos.","É usada apenas em hortas pequenas.","É a água da chuva armazenada em poços."]'::jsonb, 0, null, 'Aspersão: grandes máquinas borrifam a água por todo o terreno, como uma chuva artificial.', 'L3 p.113', 2, true),
  ('geo.c7.m2.q10', 'geo.c7.m2', 'mc', 'Para que a água é usada na pecuária?', null, '["Para saciar a sede dos animais, produzir alimentos como pastagens e rações e limpar os locais onde os animais ficam abrigados, como os currais.","Apenas para lavar os tratores.","Somente para irrigar plantações de milho.","Para produzir energia elétrica nas fazendas."]'::jsonb, 0, null, 'Na pecuária a água é essencial para os animais e para a manutenção dos lugares onde eles vivem.', 'L3 p.113', 2, true),
  ('geo.c7.m2.q11', 'geo.c7.m2', 'mc', 'De que a melancia precisa para se desenvolver?', null, '["De bastante água — por isso é preciso observar o período de chuvas — e de uma terra em boas condições, com o solo preparado e com nutrientes.","Apenas de luz do Sol.","Somente de adubo, sem água.","De água salgada."]'::jsonb, 0, null, 'Antes de plantar, é preciso verificar a disponibilidade de água na região e preparar o solo, vendo se ele precisa de nutrientes.', 'L3 p.108 e p.109', 2, true),
  ('geo.c7.m2.q12', 'geo.c7.m2', 'mc', 'Qual recurso natural faltou no texto e qual atividade foi prejudicada?', 'No Rio Grande do Sul, o problema é a falta de chuva. No município de Hulha Negra, um produtor rural perdeu 80% da produção de leite. A pastagem, plantada em dezembro, não cresceu e faltou comida para os animais.', '["Faltou água, e a atividade prejudicada foi a pecuária.","Faltou solo, e a atividade prejudicada foi a indústria.","Faltou ar, e a atividade prejudicada foi a agricultura.","Faltou energia elétrica, e a atividade prejudicada foi o comércio."]'::jsonb, 0, null, 'Sem chuva, a pastagem não cresceu e faltou comida para o gado — por isso a produção de leite caiu.', 'L3 p.116, atividade 5', 2, true),
  ('geo.c7.m2.q13', 'geo.c7.m2', 'mc', 'Por que a água dos mares e oceanos não serve para o consumo humano?', null, '["Porque ela é salgada e, por isso, imprópria para o consumo humano.","Porque ela é muito fria.","Porque ela está longe das cidades.","Porque ela está poluída por lixões."]'::jsonb, 0, null, 'Na superfície terrestre há água doce e salgada. A dos mares e oceanos é salgada. A água doce é a própria para consumo.', 'L3 p.117', 2, true),
  ('geo.c7.m2.q14', 'geo.c7.m2', 'vf', 'A maior parte da água da Terra é doce e própria para o consumo.', null, '["Verdadeiro","Falso"]'::jsonb, 1, null, 'Falso! A maior parte da água da Terra é salgada e está nos mares e oceanos. Apenas uma pequena quantidade é doce — por isso precisamos preservá-la.', 'L3 p.117', 2, true),
  ('geo.c7.m2.q15', 'geo.c7.m2', 'mc', 'Onde podemos encontrar a água doce que está na superfície?', null, '["Em rios, lagos, lagoas, riachos e represas.","Apenas nos mares e oceanos.","Somente nas geleiras.","Somente dentro das indústrias."]'::jsonb, 0, null, 'Parte da água doce fica na superfície, em rios, lagos, lagoas, riachos, represas etc.', 'L3 p.117', 2, true),
  ('geo.c7.m2.q16', 'geo.c7.m2', 'mc', 'O que é o lençol freático?', null, '["O local abaixo da superfície terrestre onde a água doce fica armazenada; ela pode ser retirada por meio de poços.","Um tipo de represa construída pelas pessoas.","O nome da água salgada dos oceanos.","Uma máquina que irriga plantações."]'::jsonb, 0, null, 'Parte da água doce está abaixo da superfície e é retirada pela construção de poços. Esse local se chama lençol freático.', 'L3 p.117', 2, true),
  ('geo.c7.m2.q17', 'geo.c7.m2', 'mc', 'Além dos rios e dos lençóis freáticos, onde mais existe água doce?', null, '["Nas geleiras e na forma de chuva, granizo e neve.","Somente nos mares.","Somente nas piscinas.","Somente nas usinas hidrelétricas."]'::jsonb, 0, null, 'Há água doce também nas geleiras e nas diferentes formas de precipitação: chuva, granizo e neve.', 'L3 p.117', 2, true),
  ('geo.c7.m2.q18', 'geo.c7.m2', 'mc', 'O que o livro conta sobre a energia gerada pelo vento no Brasil?', null, '["O país está entre os dez do mundo que mais produzem energia a partir do vento.","O Brasil não produz energia com o vento.","Só o Rio Grande do Norte produz esse tipo de energia.","O vento só serve para refrescar as pessoas."]'::jsonb, 0, null, 'No Brasil os ventos geram muita energia elétrica, como no parque eólico de Galinhos, no Rio Grande do Norte.', 'L3 p.106', 2, true)
